import React, { useEffect, useState } from 'react'
import { useAuth } from '../context/AuthContext'

import axiosInstance from '../api/axiosInstance'

export function MyTeam() {
    const [team, setTeam] = useState('')
    const { user } = useAuth()
    const [myTeam, steMyTeam] = useState(null)
    async function handleTeamCreate(e) {
        e.preventDefault()
        const response = await axiosInstance.post("/team/create", { name: team })

    }

    useEffect(() => {
        async function fetchMyTeam() {
            try {
                const response = await axiosInstance.get("team/myteam")
               steMyTeam(response.data);
            }
            catch (error) {
                console.log(error.response.data);

            }
            fetchMyTeam()
        }

    },[])
    return (
        <div><h1>Team's</h1>

            <form onSubmit={handleTeamCreate}>
                <label >Team Name</label><input type="text" onChange={(e) => { setTeam(e.target.value) }} value={team} />
                <button>Create</button>
            </form>
            <div><h1>My Team</h1>
            <div>
                {fetchMyTeam.map((team)=>{
                    <p></p>
                })}
            </div>

            </div>


        </div>
    )
}
